function validate([startTime, endTime, queryTime]) {
  if (startTime.length < 1 || startTime.length > 100) return 'startTime needs 1 to 100 values.';
  if (endTime.length !== startTime.length) return 'startTime and endTime must have the same length.';
  for (let i = 0; i < startTime.length; i++) {
    if (startTime[i] < 1 || endTime[i] > 1000 || startTime[i] > endTime[i]) return 'Each interval needs 1 <= startTime[i] <= endTime[i] <= 1000.';
  }
  if (queryTime < 1 || queryTime > 1000) return 'queryTime is between 1 and 1000.';
  return null;
}

