function busyStudent(startTime, endTime, queryTime) {
  // Mark every time each student was busy, then read the mark at queryTime.
  const busy = new Array(1002).fill(0);
  startTime.forEach((s, i) => { for (let t = s; t <= endTime[i]; t++) busy[t]++; });
  return busy[queryTime];
}

