function generate(rand, size) {
  const n = size === 'large' ? 100 : 1 + Math.floor(rand() * 8);
  const limit = size === 'large' ? 1000 : 3 + Math.floor(rand() * 15);
  const startTime = [], endTime = [];
  for (let i = 0; i < n; i++) {
    const a = 1 + Math.floor(rand() * limit), b = 1 + Math.floor(rand() * limit);
    startTime.push(Math.min(a, b));
    endTime.push(Math.max(a, b));
  }
  return [startTime, endTime, 1 + Math.floor(rand() * limit)];
}
